// === Tab: mySketch ===
var seed = "openprocessing";
var nums = 220;
var maxLife = 110;
var noiseScale = 240;
var fadeFrame = 0;

var particles = [];
var backgroundColor;
var collisionDistance = 18;

function setup() {
  createCanvas(windowHeight, windowHeight);
  pixelDensity(2);
  colorMode(RGB, 255, 255, 255, 255);
  strokeCap(ROUND);
  strokeJoin(ROUND);
  backgroundColor = color(6, 7, 10);
  resetSketch();
}

function resetSketch() {
  randomSeed(seed + frameCount * 10);
  noiseSeed(frameCount + 999);

  background(backgroundColor);
  particles = [];

  for (var i = 0; i < nums; i++) {
    particles[i] = new Particle();
    particles[i].respawnCenter();
  }
}

function draw() {
  fadeFrame++;

  // fondo suave para conservar estela
  blendMode(BLEND);
  noStroke();
  fill(6, 7, 10, 12);
  rect(0, 0, width, height);

  detectCollisions();

  // líneas
  blendMode(ADD);
  for (var i = 0; i < nums; i++) {
    particles[i].move();
    particles[i].checkEdge();
    particles[i].display();
  }

  // brillo central leve para look póster
  drawCenterGlow();
}

function drawCenterGlow() {
  blendMode(SCREEN);
  noStroke();
  for (var i = 0; i < 3; i++) {
    fill(180, 185, 200, 8 - i * 2);
    ellipse(width / 2, height / 2, 70 + i * 45, 70 + i * 45);
  }
}

function detectCollisions() {
  for (var i = 0; i < nums; i++) {
    particles[i].colliding = false;
  }

  for (var i = 0; i < nums; i++) {
    for (var j = i + 1; j < nums; j++) {
      var d = dist(
        particles[i].pos.x, particles[i].pos.y,
        particles[j].pos.x, particles[j].pos.y
      );

      if (d < collisionDistance) {
        particles[i].activateCollision(particles[j].pos);
        particles[j].activateCollision(particles[i].pos);
      }
    }
  }
}

function keyReleased() {
  if (key == 'r' || key == 'R' || keyCode == 32) {
    resetSketch();
  }

  if (key == 's' || key == 'S') {
    save("poster_gray_red_noise_" + frameCount + ".jpg");
  }
}

function Particle() {
  this.center = createVector(width / 2, height / 2);
  this.pos = this.center.copy();
  this.prev = this.pos.copy();
  this.vel = p5.Vector.random2D();

  this.life = maxLife;

  // mezcla de ritmos
  this.speedFactor = random() < 0.55 ? random(0.55, 1.0) : random(1.4, 2.6);

  // líneas más finas y elegantes
  this.weight = random(0.04, 0.22);

  // gama de plomos refinada
  this.grayA = random(90, 130);
  this.grayB = random(170, 230);

  this.colliding = false;
  this.collisionFlash = 0;
  this.impactPoint = null;

  this.noiseBurst = false;
  this.noiseBurstTimer = 0;

  this.angleOffset = random(TWO_PI);
  this.radialSpeed = random(0.7, 1.8);
  this.swirl = random(-0.12, 0.12);

  this.move = function() {
    this.prev = this.pos.copy();
    this.life--;

    if (this.life <= 0) {
      this.respawnCenter();
    }

    if (this.noiseBurst) {
      // movimiento caótico después del choque
      var ang = noise(
        this.pos.x / noiseScale,
        this.pos.y / noiseScale,
        frameCount * 0.012 + this.angleOffset
      ) * TWO_PI * 4.5;

      var outward = p5.Vector.sub(this.pos, this.center);
      if (outward.mag() < 1) {
        outward = p5.Vector.fromAngle(this.angleOffset);
      }
      outward.normalize();

      var noiseVec = createVector(cos(ang), sin(ang)).mult(1.2);
      var escapeVec = outward.mult(2.6 * this.speedFactor);

      this.vel = p5.Vector.add(noiseVec, escapeVec);
      this.pos.add(this.vel);

      this.noiseBurstTimer--;
      if (this.noiseBurstTimer <= 0) {
        this.noiseBurst = false;
      }

    } else {
      // expansión limpia desde el centro
      var dir = p5.Vector.sub(this.pos, this.center);

      if (dir.mag() < 1) {
        dir = p5.Vector.fromAngle(this.angleOffset);
      }

      dir.normalize();

      var outward = dir.copy().mult(this.radialSpeed * this.speedFactor);
      var tangent = createVector(-dir.y, dir.x).mult(this.swirl);

      // leve modulación para que no sea rígido
      var n = noise(
        this.pos.x * 0.002,
        this.pos.y * 0.002,
        frameCount * 0.003
      );
      outward.rotate(map(n, 0, 1, -0.08, 0.08));

      this.vel = outward.add(tangent);
      this.pos.add(this.vel);

      this.radialSpeed *= 1.0018;
    }

    if (this.collisionFlash > 0) {
      this.collisionFlash--;
    }
  };

  this.activateCollision = function(otherPos) {
    this.colliding = true;
    this.collisionFlash = 34;
    this.impactPoint = p5.Vector.add(this.pos, otherPos).mult(0.5);

    this.noiseBurst = true;
    this.noiseBurstTimer = 36;
  };

  this.checkEdge = function() {
    var margin = 60;
    if (
      this.pos.x < -margin ||
      this.pos.x > width + margin ||
      this.pos.y < -margin ||
      this.pos.y > height + margin
    ) {
      this.respawnCenter();
    }
  };

  this.respawnCenter = function() {
    var r = random(2, 20);
    var a = random(TWO_PI);

    this.pos = createVector(
      width / 2 + cos(a) * r,
      height / 2 + sin(a) * r
    );

    this.prev = this.pos.copy();
    this.life = maxLife;

    this.speedFactor = random() < 0.55 ? random(0.55, 1.0) : random(1.4, 2.6);
    this.weight = random(0.04, 0.22);

    this.grayA = random(90, 130);
    this.grayB = random(170, 230);

    this.colliding = false;
    this.collisionFlash = 0;
    this.impactPoint = null;

    this.noiseBurst = false;
    this.noiseBurstTimer = 0;

    this.angleOffset = random(TWO_PI);
    this.radialSpeed = random(0.7, 1.8);
    this.swirl = random(-0.12, 0.12);
  };

  this.display = function() {
    var c;

    if (this.collisionFlash > 0) {
      var t = map(this.collisionFlash, 0, 34, 0.15, 1, true);

      // rojo cinematográfico
      c = lerpColor(
        color(90, 18, 18, 90),
        color(255, 55, 45, 240),
        t
      );

      stroke(c);
      strokeWeight(this.weight * 1.8);
      line(this.prev.x, this.prev.y, this.pos.x, this.pos.y);

      // halo del choque
      if (this.impactPoint) {
        noStroke();
        fill(255, 60, 50, 40);
        ellipse(this.impactPoint.x, this.impactPoint.y, 16, 16);

        fill(255, 70, 60, 18);
        ellipse(this.impactPoint.x, this.impactPoint.y, 34, 34);
      }

    } else {
      var mix = map(this.speedFactor, 0.55, 2.6, 0, 1, true);
      c = lerpColor(
        color(this.grayA, this.grayA, this.grayA, 70),
        color(this.grayB, this.grayB, this.grayB, 135),
        mix
      );

      stroke(c);
      strokeWeight(this.weight);
      line(this.prev.x, this.prev.y, this.pos.x, this.pos.y);
    }
  };
}

